--
-- Name: dime_barangay_aggregates; Type: VIEW; Schema: public; Owner: budget_admin
--

CREATE VIEW public.dime_barangay_aggregates AS
 SELECT projects.barangay,
    projects.region,
    projects.province,
    projects.city,
    count(*) AS project_count,
    sum(projects.cost) AS total_amount,
    avg(projects.cost) AS avg_amount,
    min(projects.cost) AS min_amount,
    max(projects.cost) AS max_amount,
    round(((sum(projects.cost) / ( SELECT sum(projects_1.cost) AS sum
           FROM public.projects projects_1
          WHERE (projects_1.cost IS NOT NULL))) * (100)::numeric), 2) AS percentage_of_total
   FROM public.projects
  WHERE ((projects.barangay IS NOT NULL) AND (projects.barangay <> ''::text) AND (projects.barangay <> 'N/A'::text) AND (projects.cost IS NOT NULL))
  GROUP BY projects.barangay, projects.region, projects.province, projects.city
  ORDER BY (sum(projects.cost)) DESC
 LIMIT 100;


