--
-- Name: dime_basic_stats; Type: VIEW; Schema: public; Owner: budget_admin
--

CREATE VIEW public.dime_basic_stats AS
 SELECT count(*) AS total_projects,
    sum(projects.cost) AS total_budget,
    avg(projects.cost) AS avg_cost,
    count(DISTINCT projects.region) AS regions_covered,
    sum(
        CASE
            WHEN (projects.status = ANY (ARRAY['On-going'::text, 'Ongoing'::text])) THEN 1
            ELSE 0
        END) AS active_projects
   FROM public.projects;


