--

CREATE VIEW public.dime_progress_distribution AS
 SELECT
        CASE
            WHEN (projects.status = 'Completed'::text) THEN '75-100%'::text
            WHEN (projects.status = ANY (ARRAY['Ongoing'::text, 'On-going'::text])) THEN '50-75%'::text
            WHEN (projects.status = 'Not Yet Started'::text) THEN '0-25%'::text
            ELSE 'Unknown'::text
        END AS range,
    count(*) AS count,
    round((((count(*))::numeric / (( SELECT count(*) AS count
           FROM public.projects projects_1))::numeric) * (100)::numeric), 2) AS percentage
   FROM public.projects
  GROUP BY
        CASE
            WHEN (projects.status = 'Completed'::text) THEN '75-100%'::text
            WHEN (projects.status = ANY (ARRAY['Ongoing'::text, 'On-going'::text])) THEN '50-75%'::text
            WHEN (projects.status = 'Not Yet Started'::text) THEN '0-25%'::text
            ELSE 'Unknown'::text
        END
  ORDER BY
        CASE
            WHEN (projects.status = 'Completed'::text) THEN '75-100%'::text
            WHEN (projects.status = ANY (ARRAY['Ongoing'::text, 'On-going'::text])) THEN '50-75%'::text
            WHEN (projects.status = 'Not Yet Started'::text) THEN '0-25%'::text
            ELSE 'Unknown'::text
        END;


